-- Thiết lập encoding UTF-8 cho tiếng Việt
SET NAMES 'utf8mb4';
SET CHARACTER SET utf8mb4;
SET character_set_connection = utf8mb4;
SET collation_connection = utf8mb4_unicode_ci;

-- Tắt kiểm tra Foreign Key để import không bị lỗi thứ tự
SET @OLD_FOREIGN_KEY_CHECKS = @@FOREIGN_KEY_CHECKS;
SET FOREIGN_KEY_CHECKS = 0;

-- Tắt UNIQUE_CHECKS để tăng tốc import
SET @OLD_UNIQUE_CHECKS = @@UNIQUE_CHECKS;
SET UNIQUE_CHECKS = 0;

-- KHÔNG hardcode USE database_name ở đây
-- Khi import, chỉ định database trên command line:
-- mysql -u root -p TEN_DATABASE < exported_data.sql

